def is_costas(n, fixed):
    pos = [-1] * n
    used_row = [False] * n
    used_diffs = set()

    def backtrack(c):
        if c == n:
            return True
        candidates = [fixed[c]] if c in fixed else range(n)
        for r in candidates:
            if used_row[r]:
                continue
            # check new diffs
            conflict = False
            new_diffs = []
            for prev in range(c):
                dc = c - prev
                dr = r - pos[prev]
                diff = (dc, dr)
                if diff in used_diffs:
                    conflict = True
                    break
                new_diffs.append(diff)
            if conflict:
                continue
            # place
            pos[c] = r
            used_row[r] = True
            for d in new_diffs:
                used_diffs.add(d)
            if backtrack(c + 1):
                return True
            # backtrack
            for d in new_diffs:
                used_diffs.remove(d)
            used_row[r] = False
            pos[c] = -1
        return False

    if backtrack(0):
        return pos
    return None

fixed = {4: 3, 9: 1}
result = is_costas(13, fixed)
print(result)
